  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C73"],
      "claim": "Propranolol, a high-transfer analogue, showed absolute oral bioavailability as low as 16% after an 80-mg oral dose, demonstrating that extensive first-pass metabolism can produce F below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Labetalol, another high-transfer analogue, has an oral bioavailability of only 18% in a 70 kg human, supporting low F for a drug with high hepatic extraction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Ilomastat, a peptide-like analogue, did not show good oral bioavailability, supporting low F for a molecule with multiple polar groups and metabolic liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rosuvastatin, the closest statin analogue, has an absolute oral bioavailability of approximately 20%, at the threshold; this is contradictory to low but does not establish high for the query because the query has greater first-pass liability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is atorvastatin, whose absolute oral bioavailability is approximately 14%, below the 20% threshold. The closest statin analogue rosuvastatin is at the threshold, but the query's pyrrole/anilide core and CYP3A4-mediated first-pass metabolism favor lower F. High-transfer beta-blocker records with F below 20% corroborate that extensive first-pass extraction can produce low oral bioavailability.",
  "evidence_gaps": [
    "No direct atorvastatin oral bioavailability record was supplied; the closest statin evidence is rosuvastatin at the 20% threshold.",
    "High-transfer beta-blocker records are not structurally matched to the statin core, limiting directness."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

